struct LedgerGoldenCase {
    let name: String
    let schema: LedgerSchema
    let base: String?
    let local: String
    let remote: String
    let expected: String
    let equalsRemote: Bool
    let added: [String]
    let changed: [String]
    let removed: [String]
    let resurrected: [String]
    let keptDeleted: [String]
    let unreadable: [String]
    let conflicts: Int
    let selfCheckOK: Bool
}

struct LedgerGoldenEditable {
    let name: String
    let schema: LedgerSchema
    let raw: String
    let editable: Bool
}

enum LedgerMergeGolden {
    struct Report {
        let passed: Int
        let total: Int
        let failures: [String]
        var allPassed: Bool { passed == total && total > 0 }
    }

    static func run() -> Report {
        var passed = 0
        var failures: [String] = []
        for c in cases {
            if check(c) { passed += 1 } else { failures.append(c.name) }
        }
        for e in editableCases {
            if checkEditable(e) { passed += 1 } else { failures.append(e.name) }
        }
        return Report(passed: passed, total: cases.count + editableCases.count, failures: failures)
    }

    private static func check(_ c: LedgerGoldenCase) -> Bool {
        let baseData: Data? = c.base.map { s in Data(s.utf8) }
        let remoteData = Data(c.remote.utf8)
        guard let r = LedgerMerge.threeWay(c.schema, base: baseData, local: Data(c.local.utf8), remote: remoteData),
              let want = LedgerMerge.parseArray(Data(c.expected.utf8)) else { return false }
        guard NSArray(array: r.array).isEqual(to: want), r.equalsRemote == c.equalsRemote else { return false }
        guard r.added == c.added, r.changed == c.changed, r.removed == c.removed else { return false }
        guard r.resurrected == c.resurrected, r.keptDeleted == c.keptDeleted, r.unreadable == c.unreadable else { return false }
        guard r.conflicts.count == c.conflicts else { return false }
        let expect = LedgerMerge.Expectation(added: Set(r.added), edited: Set(r.changed + r.resurrected), removed: Set(r.removed))
        let problems = LedgerMerge.selfCheck(c.schema, remote: remoteData, result: r, expect: expect)
        return problems.isEmpty == c.selfCheckOK
    }

    private static func checkEditable(_ e: LedgerGoldenEditable) -> Bool {
        guard let raw = (try? JSONSerialization.jsonObject(with: Data(e.raw.utf8), options: [])) as? [String: Any] else { return false }
        return LedgerMerge.editable(e.schema, raw: raw) == e.editable
    }

